"""Freeze synthetic dev/control cases before running live evaluation."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
rows=[]
def add(q,ids,checks,group='faq',history=None,route='answer'):
 rows.append(dict(id=f'T{len(rows)+1:03}',group=group,query=q,expected_ids=ids.split(),checks=checks,history=history or [],expected_route=route))
