assert len(rows)==80
(ROOT/'evaluation/control.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
dev=[('Что у вас можно оформить?','G01'),('Нужна обычная карта для покупок','D01'),('Как заказать Каждый день?','D02'),('Получил пластик, что дальше?','D03'),('Какие бонусы на дебетовке?','D04'),('Расскажите о кредитке','C01'),('Документы на Запас','C02'),('Как работает грейс?','C03'),('Можно снимать с кредитки?','C04'),('Ищу карту школьнику','J01'),('Что нужно родителю для Старт?','J02'),('Где менять лимиты ребёнку?','J03'),('Открытие Копилки','S02'),('Копилка доход','S03'),('Хочу фиксированную ставку','V01'),('Горизонт раньше срока','V04'),('Кредит наличными условия','L01'),('Документы на План','L02'),('Где взять выписку','G04'),('Чем различаются сбережения?','G02')]
